for i,(r,c) in enumerate(pts):
 for rr,cc in pts[i+1:]:
  g=math.gcd(abs(rr-r),abs(cc-c))
  if g>1 and r!=rr and c!=cc:
   for k in range(1,g):extra.add((r+(rr-r)*k//g,c+(cc-c)*k//g))
